const __gub=(r,seat,vr,rs)=>{if(!String(vr).split('\n').some(l=>/^\[AUDIT v4\d: .*\(pkgUND\)/.test(l)&&l.includes('SEAT: '+seat+';')&&new RegExp('(ITEMS: |\\); )'+r.src.slice(8)+' \\(').test(l)))return true;const it=(PASS.sb_items||[]).find(x=>x.seat===seat&&'E-APPLY '+x.sid===r.src)||{rule:'E-HOLD'};const q=n=>{try{return n.isExecuted?n.all().map(i=>i.json):[];}catch(e){return [];}};let x=r;for(let n=0,m;n<9&&(m=/later gate change (G\d+)/.exec(String(x.why)));n++){const y=(rs||[]).find(q=>q.gid===m[1]);if(!y)break;x=y;}try{return UND.cure(it,{ans:'CHANGE',to:x.to},{rows:q($('Cited Verses')).filter(x=>x&&x.book),ow:q($('L2 Words')).filter(x=>x&&x.book),lex:q($('L2 Lexicon')).filter(x=>x&&x.strongs_number)}).status==='CURED';}catch(e){return false;}}; /* pkgGUB: a line counted by pkgUND loses its count only when the gate's new line passes that rule; a cure by a later gate change is read on that change's line, the line in effect */
